<?php
require __DIR__.'/primary_auxiliary.php';
require_once APPPATH.'services/NativeCompanyCatalogUi.php';
$db->query("CREATE TABLE {$p}items(id {$auto},description TEXT,long_description TEXT,rate DECIMAL(15,2),unit TEXT,tax INT,tax2 INT,group_id INT,rate_currency_2 DECIMAL(15,2))");
$db->query("CREATE TABLE {$p}items_groups(id {$auto},name TEXT)");
$db->query("CREATE TABLE {$p}taxes(id {$auto},name TEXT,taxrate DECIMAL(15,2))");
$db->query("INSERT INTO {$p}taxes(id,name,taxrate) VALUES(1,'Historical tax',5)");
$db->query("INSERT INTO {$p}items_groups(id,name) VALUES(1,'Historical group')");
$db->query("INSERT INTO {$p}items(id,description,long_description,rate,unit,tax,group_id,rate_currency_2) VALUES(1,'Historical item','Kept',12,'un',1,1,19)");
$db->query("CREATE TABLE {$p}customfields(id INTEGER PRIMARY KEY,fieldto TEXT,field_order INT)");
$ui=new NativeCompanyCatalogUi($db,$p,$principal,7);
$namedCatalog=new NativeCompanyCatalogUi($db,$p,41,7);
$tax=$namedCatalog->saveTax(['name'=>'Secondary tax','taxrate'=>'6']);$group=$namedCatalog->saveGroup(['name'=>'Secondary group']);
$id=$namedCatalog->saveItem(['description'=>'Secondary item','rate'=>'2','tax'=>$tax,'group_id'=>$group]);
essentialCheck(count($ui->taxes())===1&&count($ui->groups())===1,'principal catalogue retains native historical tables only');
$row=$ui->item('1');essentialCheck($row['source_kind']==='item'&&$row['taxid']==1&&$row['rate_currency_2']==19&&strlen($row['revision'])===64,'historical currency and references preserved with fingerprint');
essentialCheck($namedCatalog->item($id)['source_kind']==='company_item'&&$namedCatalog->item($id)['taxid']===$tax,'secondary owned IDs never alias historical references');
$page=$ui->itemTable(0,1);essentialCheck($page['total']===1&&$page['rows'][0]['id']==='1','principal pagination does not inherit secondary catalogue');
essentialCheck(count($ui->search('item'))===1,'principal search preserves native catalogue');
$named=new NativeCompanyCatalogUi($db,$p,41,7);settingThrows(fn()=>$named->item('1'),'company_catalog_denied','named company cannot hydrate principal raw item');
essentialCheck(!in_array('Historical tax',array_column($named->taxes(),'name'),true),'historical taxes never leak into named company');
echo "Principal historical and secondary owned catalogue identifiers and isolation: passed.\n";
